    head: { s: 'afficher le début des fichiers', y: 'head [OPTION]... [FICHIER]...', d: 'Affiche les 10 premières lignes de chaque FICHIER. Avec plusieurs fichiers, chacun est précédé de son nom.', o: [['-n, --lines=[-]N', 'affiche les N premières lignes ; avec -N, tout sauf les N dernières'], ['-c, --bytes=[-]N', 'affiche les N premiers octets'], ['-N', 'raccourci de -n N'], ['-q', 'pas de nom de fichier']], e: [['head fichier', '10 premières lignes'], ['head -n 5 fichier', '5 premières lignes'], ['head -c 10 fichier', '10 premiers octets'], ['head -n 90 f | tail -n 1', 'la 90e ligne'], ['head -n -1 f', 'tout sauf la dernière ligne']], v: 'tail(1), cat(1)', k: 'début premières lignes octets' },
